SELECT generico5.categoria AS categoria FROM generico5 WHERE ((generico5.anunciante IN ('BANTRAB/TODOTICKET', 'TODOTICKET', 'TODOTICKET.COM')) AND (CAST(EXTRACT(YEAR FROM generico5.fecha) AS SIGNED) >= 2010) AND (CAST(EXTRACT(YEAR FROM generico5.fecha) AS SIGNED) <= 2015) AND (((CAST(EXTRACT(MONTH FROM generico5.fecha) AS SIGNED) >= 1) AND (CAST(EXTRACT(MONTH FROM generico5.fecha) AS SIGNED) <= 7)) OR (CAST(EXTRACT(MONTH FROM generico5.fecha) AS SIGNED) IS NULL))) GROUP BY generico5.categoria;
